        body.innerHTML = panel('People responsible for the outcome', `<div class="panel-body">${lineItems(d.advisers.map(a => [`${esc(a.name)}<small class="person-meta">${esc(a.role)} · ${esc(a.reason)}</small>`, badge(a.status, a.status === 'leave' ? 'amber' : '')]))}${d.coverage.map(c => `<div class="callout">${esc(c.covering_name)} covers until ${instant(c.ends_at)}. ${esc(c.reason)}</div>`).join('')}</div>`) + panel('Permissions & scoped exceptions', `<div class="panel-body">${lineItems(d.consents.map(c => [`${esc(c.delegate_name)} · ${esc(c.scope)}<small class="person-meta">${date(c.starts_at)} → ${date(c.expires_at)}</small>`, badge(c.revoked_at ? 'revoked' : 'active', c.revoked_at ? 'red' : '')])) || empty('No delegate consent on record')}${lineItems(d.exceptions.map(e => [`${esc(e.kind)}<small class="person-meta">${esc(e.reason)} · ${date(e.starts_at)} → ${date(e.ends_at)}</small>`, badge(e.status)]))}</div>`) + panel('Connected cases', `<div class="panel-body">${d.workflows.length ? lineItems(d.workflows.map(w => [`<a href="#workflows" class="inline-link">${esc(w.title)} ↗</a><small class="person-meta">${esc(w.owner_name)} · due ${instant(w.due_at)}</small>`, badge(w.status)])) : empty('No cross-office cases')}</div>`);
